match let new_data = Bigstringaf.create new_len in
      let old_t = { t with data_length = old_len; data = old_data } in
      t.data <- new_data;
      t.data_length <- new_len;
      t.slot_count <- (new_len / t.elt_length);
      empty_all_slots t;
      Slot.iter_all old_t
        ~f:(fun old_slot ->
              if not (Slot.is_empty old_t old_slot)
              then
                let src_off = Slot.to_offset old_slot in
                let new_slot =
                  Slot.of_elt_substring t ~src:(old_t.data) ~src_off in
                let result =
                  unguarded_add_substring t new_slot ~src:(old_t.data)
                    ~src_off in
                assert (result = `Ok))
with
| () -> _

